param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/stonecutting-final.rws'))
# Read-only original-save extraction. Does not load the game assembly or decode simple-thing compression.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function NumberOrNull($node){if($null -eq $node){return $null};return [double]::Parse($node.InnerText,[Globalization.CultureInfo]::InvariantCulture)}
function ReadThing($node){[ordered]@{id=[string]$node.id;def=[string]$node.def;pos=[string]$node.pos;count=if($node.SelectSingleNode('stackCount')){[int]$node.stackCount}else{1};stack_count_explicit=($null -ne $node.SelectSingleNode('stackCount'));spawned_tick=[int]$node.spawnedTick}}
$tables=@($s.SelectNodes('//thing[def="TableStonecutter"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;stuff=[string]$_.stuff;health=[int]$_.health;spawned_tick=[int]$_.spawnedTick;bills=@($_.SelectNodes('billStack/bills/li')|ForEach-Object{[ordered]@{recipe=[string]$_.recipe;repeat_mode=[string]$_.repeatMode;repeat_count=[int]$_.repeatCount;repeat_count_explicit=($null -ne $_.SelectSingleNode('repeatCount'));suspended=([string]$_.suspended -eq 'True');allowed_skill_range=[string]$_.allowedSkillRange;ingredients=@($_.SelectNodes('ingredientFilter/allowedDefs/li')|ForEach-Object{$_.InnerText});store_mode=[string]$_.storeMode}})}})
$granite=@($s.SelectNodes('//*[def="ChunkGranite" or def="BlocksGranite"]')|ForEach-Object{ReadThing $_}|Sort-Object {$_.id})
$p=$s.SelectSingleNode('//thing[id="Human961"]')
if(!$p){throw 'Expected experiment pawn Human961 was not found.'}
$pawn=[ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;job=[string]$p.jobs.curJob.def;job_id=[string]$p.jobs.curJob.loadID;job_started=[int]$p.jobs.curJob.startTick;target_a=[string]$p.jobs.curJob.targetA;target_b=[string]$p.jobs.curJob.targetB;job_count=(NumberOrNull $p.SelectSingleNode('jobs/curJob/count'));player_forced=([string]$p.jobs.curJob.playerForced -eq 'True');work_giver=[string]$p.jobs.curJob.workGiverDef;placed_things=@($p.SelectNodes('jobs/curJob/placedThings/li/thing')|ForEach-Object{$_.InnerText});driver=[string]$p.jobs.curDriver.GetAttribute('Class');work_left=(NumberOrNull $p.SelectSingleNode('jobs/curDriver/workLeft'));bill_start_tick=(NumberOrNull $p.SelectSingleNode('jobs/curDriver/billStartTick'));ticks_spent_recipe_work=(NumberOrNull $p.SelectSingleNode('jobs/curDriver/ticksSpentDoingRecipeWork'));food=(NumberOrNull $p.SelectSingleNode('needs/needs/li[def="Food"]/curLevel'));rest=(NumberOrNull $p.SelectSingleNode('needs/needs/li[def="Rest"]/curLevel'));hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{[ordered]@{def=[string]$_.def;severity=(NumberOrNull $_.SelectSingleNode('severity'))}});carry=@($p.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{ReadThing $_})}
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;tables=$tables;explicit_granite_things=$granite;compressed_simple_things_present=($null -ne $s.SelectSingleNode('//compressedThingMapDeflate'));inventory_scope='Explicit XML thing nodes only; compressed simple things not decoded, so empty arrays do not establish absence.';pawn=$pawn}|ConvertTo-Json -Depth 16
